1	use std::ops::Range;
2	
3	use crate::{Span, SyntaxKind, SyntaxNode, parse, reparse_block, reparse_markup};
4	
5	/// Refresh the given syntax node with as little parsing as possible.
6	///
7	/// Takes the new text, the range in the old text that was replaced and the
8	/// length of the replacement and returns the range in the new text that was
9	/// ultimately reparsed.
10	///
11	/// The high-level API for this function is
12	/// [`Source::edit`](crate::Source::edit).
13	pub fn reparse(
14	    root: &mut SyntaxNode,
15	    text: &str,
16	    replaced: Range<usize>,
17	    replacement_len: usize,
18	) -> Range<usize> {
19	    try_reparse(text, replaced, replacement_len, None, root, 0).unwrap_or_else(|| {
20	        let id = root.span().id();
21	        *root = parse(text);
22	        if let Some(id) = id {
23	            root.numberize(id, Span::FULL).unwrap();
24	        }
25	        0..text.len()
26	    })
27	}
28	
29	/// Try to reparse inside the given node, returning the range that was
30	/// ultimately reparsed.
31	///
32	/// We start by doing a depth-first search for the innermost node or nodes which
33	/// fully surround the replaced range. This can be a single node that is a
34	/// code/content block or one or more nodes that are markup expressions and are
35	/// directly inside a markup block or the top-level markup. In either case, we
36	/// call the parser and succeed only if the parsed text has balanced delimiters
37	/// with the same delimiter nesting level as before. Otherwise, we expand the
38	/// set of markup expressions outwards or return upwards until we either get a
39	/// parse that does succeed or we parse the entire text.
40	///
41	/// Note that we currently only reparse markup expressions at the top-level or
42	/// directly inside a markup block. E.g. we don't reparse markup expressions
43	/// inside lists or headings, etc. In the past we did reparse those, but the
44	/// implementation was very buggy due to edge cases surrounding indentation and
45	/// newlines, and was eventually removed without much performance impact. It's
46	/// still potentially desireable to handle some of those cases (individual list
47	/// items can get quite long in practice), but only if the implementation can be
48	/// easily reasoned as correct and shows a measured performance improvement.
49	///
50	/// We also do not currently reparse math in any capacity, but it would not be
51	/// too difficult to include equations as another kind of block, or reparse math
52	/// expressions similarly to markup expressions.
53	fn try_reparse(
54	    text: &str,
55	    replaced: Range<usize>,
56	    replacement_len: usize,
57	    parent_kind: Option<SyntaxKind>,
58	    node: &mut SyntaxNode,
59	    offset: usize,
60	) -> Option<Range<usize>> {
61	    let (overlap, start_offset) = overlapping_children(node, replaced.clone(), offset)?;
62	
63	    let node_kind = node.kind();
64	    let children = node.children_mut();
65	
66	    if let [child] = &mut children[overlap.clone()]
67	        && start_offset < replaced.start
68	        && replaced.end < start_offset + child.len()
69	        && child.is_inner()
70	    {
71	        // A single child fully surrounds the edit. We either reparse within the
72	        // child, or reparse the child itself (if the child is a block).
73	        let prev_len = child.len();
74	        let prev_desc = child.descendants();
75	        let new_len = prev_len + replacement_len - replaced.len();
76	        let new_range = start_offset..start_offset + new_len;
77	
78	        // Recursively descend and try to reparse at a lower level.
79	        if let Some(range) = try_reparse(
80	            text,
81	            replaced.clone(),
82	            replacement_len,
83	            Some(node_kind),
84	            child,
85	            start_offset,
86	        ) {
87	            // A lower level reparse succeeded! Update this node and return the
88	            // reparsed range.
89	            assert_eq!(child.len(), new_len);
90	            let new_desc = child.descendants();
91	            node.update_parent(prev_len, new_len, prev_desc, new_desc);
92	            return Some(range);
93	        }
94	
95	        // This is the innermost block which fully surrounds the text (and
96	        // hasn't failed at reparsing yet), reparse!
97	        if child.kind().is_block()
98	            && let Some(reparsed) = reparse_block(text, new_range.clone())
99	        {
100	            // Reparsing succeeded, but we can still fail if we're out of span
101	            // numbers to assign to nodes (this is rare).
102	            return node
103	                .replace_children(overlap, vec![reparsed])
104	                .is_ok()
105	                .then_some(new_range);
106	        }
107	    }
108	
109	    if node_kind == SyntaxKind::Markup
110	        && matches!(parent_kind, None | Some(SyntaxKind::ContentBlock))
111	    {
112	        expand_and_reparse_markup(
113	            text,
114	            replaced,
115	            replacement_len,
116	            node,
117	            overlap,
118	            offset,
119	            parent_kind.is_none(),
120	        )
121	    } else {
122	        None
123	    }
124	}
125	
126	/// Reparse a range of markup expressions, expanding the range exponentially on
127	/// each iteration.
128	fn expand_and_reparse_markup(
129	    text: &str,
130	    replaced: Range<usize>,
131	    replacement_len: usize,
132	    node: &mut SyntaxNode,
133	    overlap: Range<usize>,
134	    offset: usize,
135	    top_level: bool,
136	) -> Option<Range<usize>> {
137	    let children = node.children().as_slice();
138	
139	    // Reparse a segment. Retries until it works, taking exponentially more
140	    // children into account.
141	    let mut expansion = 1;
142	    loop {
143	        // Add slack in both directions.
144	        let mut start = overlap.start.saturating_sub(expansion.max(2));
145	        let mut end = (overlap.end + expansion).min(children.len());
146	
147	        // Expand to the left.
148	        while start > 0 && expand(&children[start]) {
149	            start -= 1;
150	        }
151	
152	        // Expand to the right.
153	        while end < children.len() && expand(&children[end]) {
154	            end += 1;
155	        }
156	
157	        // Also take hash.
158	        if start > 0 && children[start - 1].kind() == SyntaxKind::Hash {
159	            start -= 1;
160	        }
161	
162	        // Synthesize what `at_start` and `nesting` would be at the start of the
163	        // reparse.
164	        let mut prefix_len = 0;
165	        let mut nesting = 0;
166	        let mut at_start = true;
167	        for child in &children[..start] {
168	            prefix_len += child.len();
169	            next_at_start(child, &mut at_start);
170	            next_nesting(child, &mut nesting);
171	        }
172	
173	        // Determine what `at_start` will have to be at the end of the reparse.
174	        let mut prev_len = 0;
175	        let mut prev_at_start_after = at_start;
176	        let mut prev_nesting_after = nesting;
177	        for child in &children[start..end] {
178	            prev_len += child.len();
179	            next_at_start(child, &mut prev_at_start_after);
180	            next_nesting(child, &mut prev_nesting_after);
181	        }
182	
183	        // Determine the range in the new text that we want to reparse.
184	        let shifted = offset + prefix_len;
185	        let new_len = prev_len + replacement_len - replaced.len();
186	        let new_range = shifted..shifted + new_len;
187	        let at_end = end == children.len();
188	
189	        // Reparse!
190	        let reparsed = reparse_markup(
191	            text,
192	            new_range.clone(),
193	            &mut at_start,
194	            &mut nesting,
195	            top_level,
196	        );
197	
198	        if let Some(newborns) = reparsed {
199	            // If more children follow, at_start must match its previous value.
200	            // Similarly, if we children follow or we not top-level the nesting
201	            // must match its previous value.
202	            if (at_end || at_start == prev_at_start_after)
203	                && ((at_end && top_level) || nesting == prev_nesting_after)
204	            {
205	                // Reparsing succeeded, but we can still fail if we're out of
206	                // span numbers to assign to nodes (this is rare).
207	                return node
208	                    .replace_children(start..end, newborns)
209	                    .is_ok()
210	                    .then_some(new_range);
211	            }
212	        }
213	
214	        // If it didn't even work with all children, we give up.
215	        if start == 0 && at_end {
216	            break;
217	        }
218	
219	        // Exponential expansion to both sides.
220	        expansion *= 2;
221	    }
222	
223	    None
224	}
225	
226	/// The indices and start offset of the children which overlap a replaced range.
227	/// Returns `None` if the children don't fully cover the range. Will never
228	/// return an empty range if it returns `Some`.
229	///
230	/// Note that the returned `Range<usize>` is the range of children in the
231	/// parent, but the returned `usize` is a byte offset in the source text.
232	fn overlapping_children(
233	    node: &SyntaxNode,
234	    range: Range<usize>,
235	    mut offset: usize,
236	) -> Option<(Range<usize>, usize)> {
237	    if !node.is_inner() || offset > range.start || range.end > offset + node.len() {
238	        // No set of children will fully cover the range, no need to search.
239	        return None;
240	    }
241	    let mut index = 0;
242	    let mut start = 0;
243	    let mut start_offset = offset;
244	    for child in node.children() {
245	        if offset < range.start {
246	            start = index;
247	            start_offset = offset;
248	        }
249	        offset += child.len();
250	        index += 1;
251	        if range.end < offset {
252	            break;
253	        }
254	    }
255	    debug_assert!(start_offset <= range.start);
256	    debug_assert!(range.end <= offset);
257	    Some((start..index, start_offset))
258	}
259	
260	/// Whether the selection should be expanded beyond a node of this kind.
261	fn expand(node: &SyntaxNode) -> bool {
262	    let kind = node.kind();
263	    kind.is_trivia()
264	        || kind.is_error()
265	        || kind == SyntaxKind::Semicolon
266	        || node.leaf_text() == "/"
267	        || node.leaf_text() == ":"
268	}
269	
270	/// Whether `at_start` would still be true after this node given the
271	/// previous value of the property.
272	fn next_at_start(node: &SyntaxNode, at_start: &mut bool) {
273	    let kind = node.kind();
274	    if kind.is_trivia() {
275	        *at_start |= matches!(kind, SyntaxKind::Parbreak | SyntaxKind::SpaceWithNewline);
276	    } else {
277	        *at_start = false;
278	    }
279	}
280	
281	/// Update `nesting` based on the node.
282	fn next_nesting(node: &SyntaxNode, nesting: &mut usize) {
283	    if node.kind() == SyntaxKind::Text {
284	        match node.leaf_text().as_str() {
285	            "[" => *nesting += 1,
286	            "]" if *nesting > 0 => *nesting -= 1,
287	            _ => {}
288	        }
289	    }
290	}
