292	#[cfg(test)]
293	mod tests {
294	    use std::ops::Range;
295	
296	    use crate::{Source, Span, parse};
297	
298	    /// How to replace text in the test string.
299	    enum Edit {
300	        /// Insert at the end.
301	        End,
302	        /// Insert at an index.
303	        At(usize),
304	        /// Replace the given range.
305	        Range(Range<usize>),
306	        /// Replace the first match in the original.
307	        Match(&'static str),
308	        /// Replace at the index after the first match of this string.
309	        After(&'static str),
310	    }
311	
312	    impl Edit {
313	        #[track_caller]
314	        fn into_range(self, text: &str) -> Range<usize> {
315	            match self {
316	                Self::End => text.len()..text.len(),
317	                Self::At(index) => {
318	                    assert!(text.len() >= index, "index is out of bounds");
319	                    index..index
320	                }
321	                Self::Range(range) => {
322	                    assert!(text.len() >= range.end, "range is out of bounds");
323	                    range
324	                }
325	                Self::Match(pat) => {
326	                    let start = text.find(pat).expect("pattern must exist in original");
327	                    start..start + pat.len()
328	                }
329	                Self::After(pat) => {
330	                    let start = text.find(pat).expect("pattern must exist in original");
331	                    let end = start + pat.len();
332	                    end..end
333	                }
334	            }
335	        }
336	    }
337	
338	    /// What kind of reparsing happened.
339	    #[derive(Debug, Clone, PartialEq, Eq)]
340	    enum Reparse<'a> {
341	        /// The whole text was reparsed.
342	        All,
343	        /// The text was parsed incrementally matching this string.
344	        Incr(&'a str),
345	    }
346	
347	    #[track_caller]
348	    fn test(text: &str, edit: Edit, with: &str, expected: Reparse) {
349	        let mut source = Source::detached(text);
350	        let orig_tree = source.root().clone();
351	        // `Source::edit()` is the public interface for reparsing.
352	        let replaced_range = source.edit(edit.into_range(text), with);
353	        let mut reparsed_tree = source.root().clone();
354	        let mut normal_parse = parse(source.text());
355	        reparsed_tree.synthesize(Span::detached());
356	        normal_parse.synthesize(Span::detached());
357	        if reparsed_tree != normal_parse {
358	            eprintln!("Original source text: {text:?}");
359	            eprintln!("Original tree:\n{orig_tree:#?}");
360	            eprintln!("New source text: {:?}", source.text());
361	            eprintln!("Reparsed tree:\n{reparsed_tree:#?}");
362	            eprintln!("Normal parse tree:\n{normal_parse:#?}");
363	            panic!("Reparsed tree did not match normal parse");
364	        }
365	        let actual = if replaced_range == (0..source.text().len()) {
366	            Reparse::All
367	        } else {
368	            Reparse::Incr(&source.text()[replaced_range])
369	        };
370	        assert_eq!(actual, expected);
371	    }
372	
373	    /// Basic tests for the reparsing algorithm and the testing framework.
374	    #[test]
375	    fn test_reparse_basic() {
376	        use Reparse::*;
377	        // Replace everything with something else:
378	        test("some content", Edit::Match("some content"), "do it", All);
379	        test("some content", Edit::Range(0..12), "", All);
380	        test("", Edit::At(0), "do it", All);
381	        test("", Edit::End, "do it", All);
382	        // Add something at the end:
383	        test("some content", Edit::After("some content"), " do it", All);
384	    }
385	
386	    /// Test incremental reparsing of markup expressions.
387	    #[test]
388	    fn test_reparse_markup() {
389	        use Reparse::*;
390	        // Tilde is useful because it always creates a distinct token, whereas
391	        // spaces may join with adjacent text as one token.
392	        test("abc~def~gh~", Edit::Range(5..6), "+", Incr("abc~d+f~"));
393	        test("~~~~~~~", Edit::Range(3..4), "A", Incr("~~~A~~"));
394	        test("abc~~", Edit::Match("b"), "", Incr("ac~"));
395	        // Newlines behave slightly differently to tildes:
396	        test("~b~c~d~e", Edit::At(0), "a", Incr("a~b"));
397	        test("a~b~c~d~", Edit::End, "e", Incr("~d~e"));
398	        test("\nb\nc\nd\ne", Edit::At(0), "a", Incr("a\nb\n"));
399	        test("a\nb\nc\nd\n", Edit::End, "e", Incr("c\nd\ne"));
400	        test("#var. hello", Edit::Match(" "), " ", All);
401	        test("#var;hello", Edit::Range(9..10), "a", All);
402	        test("https:/world", Edit::After("/"), "/", All);
403	        test("hello  world", Edit::Match("world"), "walkers", All);
404	        test("a d e", Edit::Match(" d"), " b c d", All);
405	        test("~*~*~", Edit::At(2), "*", All);
406	        test("::1\n2. a\n3", Edit::After(" "), "4", Incr("1\n2. 4a\n"));
407	        test("* #{1+2} *", Edit::Match("2"), "3", Incr("{1+3}"));
408	        test("#{(0, 1, 2)}", Edit::Match("1"), "11pt", Incr("{(0, 11pt, 2)}"));
409	        test("\n= A heading", Edit::After("A"), "n evocative", All);
410	        test("#call() abc~d", Edit::After("()"), "[]", Incr("#call()[] abc"));
411	        test("a your thing a", Edit::Range(6..7), "a", All);
412	        test("#grid(columns: (auto, 1fr, 40%))", Edit::Match("auto"), "4pt", All);
413	        test(
414	            "abc\n= a head\njoke",
415	            Edit::Match("\n"),
416	            "\nmore\n\n",
417	            Incr("abc\nmore\n\n= a head\n"),
418	        );
419	        test("#show f: a => b..", Edit::End, "c", All);
420	        test("#for", Edit::End, "//", All);
421	        test("a\n#let \nb", Edit::At(7), "i", Incr("#let i\nb"));
422	        test("#{{let x = z}; a = 1} b", Edit::At(7), "//", All);
423	        test("a ```typst hello```", Edit::Range(16..17), "", All);
424	        test("a{b}c", Edit::At(1), "#", All);
425	        test("a#{b}c", Edit::Match("#"), "", All);
426	    }
427	
428	    /// Test incremental reparsing of code and content blocks.
429	    #[test]
430	    fn test_reparse_block() {
431	        use Reparse::*;
432	        test("Hello #{ x + 1 }!", Edit::Match("x"), "abc", Incr("{ abc + 1 }"));
433	        test("A#{}!", Edit::After("{"), "\"", All);
434	        test("#{ [= x] }!", Edit::After("="), "=", Incr("== x"));
435	        test("#[[]]", Edit::At(3), "\\", Incr("[[\\]]"));
436	        test("#[[ab]]", Edit::Match("b"), "\\", Incr("[[a\\]]"));
437	        test("#{}}", Edit::After("{"), "{", All);
438	        test("A: #[BC]", Edit::After("B"), "{", Incr("B{C"));
439	        test("A: #[BC]", Edit::After("B"), "#{", Incr("B#{C"));
440	        test("A: #[BC]", Edit::After("B"), "#{}", Incr("B#{}C"));
441	        test("#{\"ab\"}A", Edit::At(5), "c", Incr("{\"abc\"}"));
442	        test("#{\"ab\"}A", Edit::Range(5..6), "c", All);
443	        test("a#[]b", Edit::After("["), "#{", Incr("[#{]"));
444	        test("a#{call(); abc}b", Edit::At(8), "[]", Incr("{call([]); abc}"));
445	        test(
446	            "a #while x {\n g(x) \n}  b",
447	            Edit::After("{"),
448	            "//",
449	            Incr("{//\n g(x) \n}"),
450	        );
451	        test("a#[]b", Edit::After("["), "[hey]", Incr("[[hey]]"));
452	    }
453	
454	    /// Test unclosed strings/blocks in embedded code.
455	    #[test]
456	    fn test_reparse_unclosed_embedded() {
457	        use Reparse::*;
458	        test("#\"a\nb\nc", Edit::End, "\"", All);
459	        test("#return \"a\nb\nc", Edit::End, "\"", All);
460	        test("#import \"@preview/pkg", Edit::End, "\"", All);
461	        test("#import [a\nb\nc", Edit::End, "]", All);
462	        test("#import $a\nb\nc", Edit::End, "$", All);
463	        test("#set thing\"a\n", Edit::End, "\"", All);
464	        test("#let x = \"a\nb\nc", Edit::End, "\"", All);
465	        test("#let x = {\"a\nb\nc}", Edit::After("c"), "\"", Incr("{\"a\nb\nc\"}"));
466	        test("#if x {\"a\nb\nc", Edit::End, "\"", All);
467	        test("#if x \"a\nb\nc", Edit::End, "\"", All);
468	        test("#if x \"a\nb\nc", Edit::After("x "), "{}", All);
469	        test("#if x $a\nb\nc", Edit::End, "$", All);
470	        test("#for x in \"a\nb\nc", Edit::End, "\"", All);
471	        test("#for x \"a\nb\nc", Edit::After("x "), "in ", All);
472	    }
473	}
