21	/// Metadata about a line.
22	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
23	pub struct Line {
24	    /// The UTF-8 byte offset where the line starts.
25	    byte_idx: usize,
26	    /// The UTF-16 codepoint offset where the line starts.
27	    utf16_idx: usize,
28	}
