397	        test("abc\ndef", 7..7, "hi", "abc\ndefhi");
398	        test("abc\ndef\n", 8..8, "hi", "abc\ndef\nhi");
399	
400	        // Test appending with adjoining \r and \n.
401	        test("abc\ndef\r", 8..8, "\nghi", "abc\ndef\r\nghi");
402	
403	        // Test removing everything.
404	        test(TEST, 0..21, "", "");
405	    }
