244	/// Create a line vector.
245	fn lines(text: &str) -> Vec<Line> {
246	    std::iter::once(Line { byte_idx: 0, utf16_idx: 0 })
247	        .chain(lines_from(0, 0, text))
248	        .collect()
249	}
